// Generated by vibes-espmatter – OpenTelemetry metrics of the Panasonic heat pump.
#include "espm_otel.h"
#include "espm_pac.h"

#include <initializer_list>

static void temperature(const char *name, int16_t c)
{
    if (c == PAC_TEMP_UNKNOWN) mesp_otel_remove(name);
    else mesp_otel_gauge(name, "Cel", c);
}

/** What the unit reported as metrics; none while it doesn't answer. */
static void record(const pac_state_t &st)
{
    if (!st.valid) {
        for (const char *name : {"hvac.power", "hvac.temperature.target", "hvac.temperature.room",
                                 "hvac.temperature.outdoor", "hvac.fan.speed"})
            mesp_otel_remove(name);
        return;
    }
    mesp_otel_gauge("hvac.power", "1", st.power ? 1 : 0);
    mesp_otel_gauge("hvac.temperature.target", "Cel", st.target_x2 / 2.0);
    temperature("hvac.temperature.room", st.inside_c);
    temperature("hvac.temperature.outdoor", st.outside_c);
    // 0 = automatic
    mesp_otel_gauge("hvac.fan.speed", "1", st.fan);
}

void mesp_pac_metrics_init()
{
    mesp_pac_on_state(record);
}
